CREATE TABLE `PSS10Assessment` (`id` INTEGER NOT NULL AUTO_INCREMENT, `userId` INTEGER NOT NULL, `totalScore` INTEGER NOT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), INDEX `PSS10Assessment_userId_idx`(`userId`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `PSS10Answer` (`id` INTEGER NOT NULL AUTO_INCREMENT, `assessmentId` INTEGER NOT NULL, `questionNo` INTEGER NOT NULL, `score` INTEGER NOT NULL, UNIQUE INDEX `PSS10Answer_assessmentId_questionNo_key`(`assessmentId`, `questionNo`), INDEX `PSS10Answer_assessmentId_idx`(`assessmentId`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
ALTER TABLE `PSS10Assessment` ADD CONSTRAINT `PSS10Assessment_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `PSS10Answer` ADD CONSTRAINT `PSS10Answer_assessmentId_fkey` FOREIGN KEY (`assessmentId`) REFERENCES `PSS10Assessment`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
